453	purchase request control demo	\N	57	\N	\N	1	draft	1	2026-04-28 09:46:14.335486	2026-04-28 09:46:14.335486	<?xml version="1.0" encoding="UTF-8"?>\n<bpmn:definitions\n  xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"\n  xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"\n  xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI"\n  xmlns:dc="http://www.omg.org/spec/DD/20100524/DC"\n  xmlns:di="http://www.omg.org/spec/DD/20100524/DI"\n  xmlns:pfe="https://pfe.local/schema/bpmn"\n  id="Definitions_PurchaseRequestControlDemo"\n  targetNamespace="http://bpmn.io/schema/bpmn">\n  <bpmn:collaboration\n    id="Collaboration_PurchaseRequestControlDemo"\n    name="Purchase Request Control Demo">\n    <bpmn:participant\n      id="Participant_RequestingDepartment"\n      name="Requesting Department"\n      processRef="Process_RequestingDepartment"\n      pfe:actorNodeId="9001"\n      pfe:actorName="Sales Department"\n      pfe:actorType="org_unit"\n      pfe:actorPath="Demo Company / Commercial Division / Sales Department" />\n    <bpmn:participant\n      id="Participant_Procurement"\n      name="Procurement and Control"\n      processRef="Process_ProcurementAndControl"\n      pfe:actorNodeId="9002"\n      pfe:actorName="Procurement Department"\n      pfe:actorType="org_unit"\n      pfe:actorPath="Demo Company / Operations / Procurement Department"\n      pfe:risks='[{"id":"risk_proc_1","title":"Procurement workload saturation","severity":"medium","category":"operational","status":"monitoring","description":"A peak of approved requests can overload buyers and control staff.","mitigation":"Prioritize urgent requests and rebalance work weekly."}]' />\n    <bpmn:messageFlow\n      id="MessageFlow_ApprovedRequest"\n      name="Approved request packet"\n      sourceRef="Task_SendApprovedRequest"\n      targetRef="Task_ReceiveApprovedRequest" />\n    <bpmn:messageFlow\n      id="MessageFlow_Clarification"\n      name="Clarification required"\n      sourceRef="Task_RequestClarification"\n      targetRef="Task_PrepareRequest" />\n  </bpmn:collaboration>\n\n  <bpmn:process id="Process_RequestingDepartment" name="Requesting Department Process" isExecutable="false">\n    <bpmn:laneSet id="LaneSet_RequestingDepartment">\n      <bpmn:lane\n        id="Lane_Requester"\n        name="Requester"\n        pfe:actorNodeId="9101"\n        pfe:actorName="Amina Ben Salem"\n        pfe:actorType="function"\n        pfe:actorPath="Demo Company / Commercial Division / Sales Department / Requester">\n        <bpmn:flowNodeRef>StartEvent_RequestNeed</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_PrepareRequest</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Gateway_ManagerApprovalRequired</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_SendApprovedRequest</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>EndEvent_RequestSent</bpmn:flowNodeRef>\n      </bpmn:lane>\n      <bpmn:lane\n        id="Lane_DepartmentManager"\n        name="Department Manager"\n        pfe:actorNodeId="9102"\n        pfe:actorName="Karim Haddad"\n        pfe:actorType="manager"\n        pfe:actorPath="Demo Company / Commercial Division / Sales Department / Department Manager">\n        <bpmn:flowNodeRef>Task_ManagerReview</bpmn:flowNodeRef>\n      </bpmn:lane>\n    </bpmn:laneSet>\n\n    <bpmn:startEvent id="StartEvent_RequestNeed" name="Need identified" />\n\n    <bpmn:userTask\n      id="Task_PrepareRequest"\n      name="Prepare purchase request"\n      pfe:actorNodeId="9101"\n      pfe:actorName="Amina Ben Salem"\n      pfe:actorType="function"\n      pfe:actorPath="Demo Company / Commercial Division / Sales Department / Requester"\n      pfe:risks='[{"id":"risk_req_1","title":"Incomplete purchase specification","severity":"medium","category":"quality","status":"open","description":"The requester may omit quantity, delivery date, or supporting documents.","mitigation":"Use a mandatory request checklist before submission."}]'>\n      <bpmn:documentation>Requester completes the business need, quantity, supplier context, and desired delivery date before the workflow continues.</bpmn:documentation>\n    </bpmn:userTask>\n\n    <bpmn:exclusiveGateway\n      id="Gateway_ManagerApprovalRequired"\n      name="Manager approval required?"\n      pfe:risks='[{"id":"risk_route_1","title":"Incorrect approval routing","severity":"high","category":"operational","status":"monitoring","description":"High-value requests may bypass management approval if thresholds are misunderstood.","mitigation":"Maintain and communicate approval thresholds in the procedure manual."}]' />\n\n    <bpmn:userTask\n      id="Task_ManagerReview"\n      name="Review and approve request"\n      pfe:actorNodeId="9102"\n      pfe:actorName="Karim Haddad"\n      pfe:actorType="manager"\n      pfe:actorPath="Demo Company / Commercial Division / Sales Department / Department Manager"\n      pfe:risks='[{"id":"risk_mgr_1","title":"Approval bottleneck","severity":"medium","category":"operational","status":"open","description":"Manager availability can delay urgent requests at month end.","mitigation":"Escalate after one business day and delegate approval when absent."}]'>\n      <bpmn:documentation>Department manager validates business need, budget ownership, and urgency before the request goes to procurement.</bpmn:documentation>\n    </bpmn:userTask>\n\n    <bpmn:sendTask\n      id="Task_SendApprovedRequest"\n      name="Transmit approved request to procurement"\n      pfe:actorNodeId="9101"\n      pfe:actorName="Amina Ben Salem"\n      pfe:actorType="function"\n      pfe:actorPath="Demo Company / Commercial Division / Sales Department / Requester"\n      pfe:risks='[{"id":"risk_handoff_1","title":"Missing attachment in handoff","severity":"medium","category":"operational","status":"open","description":"The approved request packet may be sent without all supporting evidence.","mitigation":"Attach the signed request form and checklist before transmission."}]'>\n      <bpmn:documentation>Approved request packet is sent with attachments to procurement for control and ordering.</bpmn:documentation>\n    </bpmn:sendTask>\n\n    <bpmn:endEvent id="EndEvent_RequestSent" name="Request sent" />\n\n    <bpmn:sequenceFlow id="Flow_Request_1" sourceRef="StartEvent_RequestNeed" targetRef="Task_PrepareRequest" />\n    <bpmn:sequenceFlow id="Flow_Request_2" sourceRef="Task_PrepareRequest" targetRef="Gateway_ManagerApprovalRequired" />\n    <bpmn:sequenceFlow id="Flow_Request_3" name="No" sourceRef="Gateway_ManagerApprovalRequired" targetRef="Task_SendApprovedRequest" />\n    <bpmn:sequenceFlow id="Flow_Request_4" name="Yes" sourceRef="Gateway_ManagerApprovalRequired" targetRef="Task_ManagerReview" />\n    <bpmn:sequenceFlow id="Flow_Request_5" sourceRef="Task_ManagerReview" targetRef="Task_SendApprovedRequest" />\n    <bpmn:sequenceFlow id="Flow_Request_6" sourceRef="Task_SendApprovedRequest" targetRef="EndEvent_RequestSent" />\n  </bpmn:process>\n\n  <bpmn:process id="Process_ProcurementAndControl" name="Procurement and Control Process" isExecutable="false">\n    <bpmn:laneSet id="LaneSet_ProcurementAndControl">\n      <bpmn:lane\n        id="Lane_Buyer"\n        name="Buyer"\n        pfe:actorNodeId="9201"\n        pfe:actorName="Sonia Trabelsi"\n        pfe:actorType="function"\n        pfe:actorPath="Demo Company / Operations / Procurement Department / Buyer">\n        <bpmn:flowNodeRef>StartEvent_ProcurementStart</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_ReceiveApprovedRequest</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_CreatePurchaseOrder</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>EndEvent_OrderReady</bpmn:flowNodeRef>\n      </bpmn:lane>\n      <bpmn:lane\n        id="Lane_ControlOfficer"\n        name="Control Officer"\n        pfe:actorNodeId="9202"\n        pfe:actorName="Internal Control Office"\n        pfe:actorType="function"\n        pfe:actorPath="Demo Company / Operations / Internal Control / Control Officer">\n        <bpmn:flowNodeRef>Task_ComplianceCheck</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Gateway_ControlsPassed</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_RequestClarification</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>EndEvent_RequestOnHold</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>BoundaryEvent_ComplianceReviewOverdue</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>Task_EscalateControlDelay</bpmn:flowNodeRef>\n        <bpmn:flowNodeRef>EndEvent_ControlEscalated</bpmn:flowNodeRef>\n      </bpmn:lane>\n    </bpmn:laneSet>\n\n    <bpmn:startEvent id="StartEvent_ProcurementStart" name="Request received" />\n\n    <bpmn:receiveTask\n      id="Task_ReceiveApprovedRequest"\n      name="Receive approved request"\n      pfe:actorNodeId="9201"\n      pfe:actorName="Sonia Trabelsi"\n      pfe:actorType="function"\n      pfe:actorPath="Demo Company / Operations / Procurement Department / Buyer"\n      pfe:risks='[{"id":"risk_receive_1","title":"Approved request not logged","severity":"medium","category":"operational","status":"open","description":"The buyer may start work without logging the request in the tracker.","mitigation":"Register every incoming approved request before processing."}]'>\n      <bpmn:documentation>Buyer acknowledges the approved packet and checks that the request is complete before control review.</bpmn:documentation>\n    </bpmn:receiveTask>\n\n    <bpmn:businessRuleTask\n      id="Task_ComplianceCheck"\n      name="Validate compliance and control evidence"\n      pfe:actorNodeId="9202"\n      pfe:actorName="Internal Control Office"\n      pfe:actorType="function"\n      pfe:actorPath="Demo Company / Operations / Internal Control / Control Officer"\n      pfe:risks='[{"id":"risk_ctrl_1","title":"Control evidence missing","severity":"critical","category":"compliance","status":"open","description":"The procurement package may miss budget proof, supplier checks, or segregation evidence.","mitigation":"Use a control checklist and block PO creation until evidence is attached."}]'>\n      <bpmn:documentation>Control officer validates policy, budget proof, supplier screening, and segregation of duties before release.</bpmn:documentation>\n    </bpmn:businessRuleTask>\n\n    <bpmn:boundaryEvent id="BoundaryEvent_ComplianceReviewOverdue" attachedToRef="Task_ComplianceCheck" name="Compliance review overdue">\n      <bpmn:timerEventDefinition id="TimerEventDefinition_ComplianceReviewOverdue" />\n    </bpmn:boundaryEvent>\n\n    <bpmn:userTask\n      id="Task_EscalateControlDelay"\n      name="Escalate delayed control review"\n      pfe:actorNodeId="9202"\n      pfe:actorName="Internal Control Office"\n      pfe:actorType="function"\n      pfe:actorPath="Demo Company / Operations / Internal Control / Control Officer">\n      <bpmn:documentation>Escalation is sent when the control review is not completed inside the agreed SLA.</bpmn:documentation>\n    </bpmn:userTask>\n\n    <bpmn:endEvent id="EndEvent_ControlEscalated" name="Escalated" />\n\n    <bpmn:exclusiveGateway\n      id="Gateway_ControlsPassed"\n      name="Controls passed?"\n      pfe:risks='[{"id":"risk_gate_1","title":"Non-compliant request released","severity":"high","category":"compliance","status":"monitoring","description":"A request could proceed even though a key control failed.","mitigation":"Route failed controls to clarification and require a second review for overrides."}]' />\n\n    <bpmn:userTask\n      id="Task_CreatePurchaseOrder"\n      name="Create purchase order"\n      pfe:actorNodeId="9201"\n      pfe:actorName="Sonia Trabelsi"\n      pfe:actorType="function"\n      pfe:actorPath="Demo Company / Operations / Procurement Department / Buyer"\n      pfe:risks='[{"id":"risk_po_1","title":"Wrong purchase order data","severity":"medium","category":"financial","status":"open","description":"Incorrect supplier or pricing data can be copied into the purchase order.","mitigation":"Validate supplier, amount, and currency fields before final issue."}]'>\n      <bpmn:documentation>Buyer creates the purchase order after compliance approval and checks final supplier and amount data.</bpmn:documentation>\n    </bpmn:userTask>\n\n    <bpmn:endEvent id="EndEvent_OrderReady" name="PO ready" />\n\n    <bpmn:manualTask\n      id="Task_RequestClarification"\n      name="Request clarification from requester"\n      pfe:actorNodeId="9202"\n      pfe:actorName="Internal Control Office"\n      pfe:actorType="function"\n      pfe:actorPath="Demo Company / Operations / Internal Control / Control Officer">\n      <bpmn:documentation>Control officer returns the packet for clarification or missing evidence before the request can proceed.</bpmn:documentation>\n    </bpmn:manualTask>\n\n    <bpmn:endEvent id="EndEvent_RequestOnHold" name="On hold" />\n\n    <bpmn:sequenceFlow id="Flow_Proc_1" sourceRef="StartEvent_ProcurementStart" targetRef="Task_ReceiveApprovedRequest" />\n    <bpmn:sequenceFlow id="Flow_Proc_2" sourceRef="Task_ReceiveApprovedRequest" targetRef="Task_ComplianceCheck" />\n    <bpmn:sequenceFlow id="Flow_Proc_3" sourceRef="Task_ComplianceCheck" targetRef="Gateway_ControlsPassed" />\n    <bpmn:sequenceFlow id="Flow_Proc_4" name="Yes" sourceRef="Gateway_ControlsPassed" targetRef="Task_CreatePurchaseOrder" />\n    <bpmn:sequenceFlow id="Flow_Proc_5" sourceRef="Task_CreatePurchaseOrder" targetRef="EndEvent_OrderReady" />\n    <bpmn:sequenceFlow id="Flow_Proc_6" name="No" sourceRef="Gateway_ControlsPassed" targetRef="Task_RequestClarification" />\n    <bpmn:sequenceFlow id="Flow_Proc_7" sourceRef="Task_RequestClarification" targetRef="EndEvent_RequestOnHold" />\n    <bpmn:sequenceFlow id="Flow_Proc_8" sourceRef="BoundaryEvent_ComplianceReviewOverdue" targetRef="Task_EscalateControlDelay" />\n    <bpmn:sequenceFlow id="Flow_Proc_9" sourceRef="Task_EscalateControlDelay" targetRef="EndEvent_ControlEscalated" />\n  </bpmn:process>\n\n  <bpmndi:BPMNDiagram id="BPMNDiagram_PurchaseRequestControlDemo">\n    <bpmndi:BPMNPla