x="250" y="470" width="150" height="86" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="Task_ComplianceCheck_di" bpmnElement="Task_ComplianceCheck">\n        <dc:Bounds x="520" y="615" width="180" height="90" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="BoundaryEvent_ComplianceReviewOverdue_di" bpmnElement="BoundaryEvent_ComplianceReviewOverdue">\n        <dc:Bounds x="592" y="687" width="36" height="36" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="Task_EscalateControlDelay_di" bpmnElement="Task_EscalateControlDelay">\n        <dc:Bounds x="760" y="710" width="180" height="70" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="EndEvent_ControlEscalated_di" bpmnElement="EndEvent_ControlEscalated">\n        <dc:Bounds x="1030" y="727" width="36" height="36" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="Gateway_ControlsPassed_di" bpmnElement="Gateway_ControlsPassed" isMarkerVisible="true">\n        <dc:Bounds x="760" y="635" width="50" height="50" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="Task_CreatePurchaseOrder_di" bpmnElement="Task_CreatePurchaseOrder">\n        <dc:Bounds x="930" y="470" width="160" height="86" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="EndEvent_OrderReady_di" bpmnElement="EndEvent_OrderReady">\n        <dc:Bounds x="1170" y="495" width="36" height="36" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="Task_RequestClarification_di" bpmnElement="Task_RequestClarification">\n        <dc:Bounds x="930" y="615" width="170" height="90" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="EndEvent_RequestOnHold_di" bpmnElement="EndEvent_RequestOnHold">\n        <dc:Bounds x="1180" y="642" width="36" height="36" />\n      </bpmndi:BPMNShape>\n\n      <bpmndi:BPMNEdge id="Flow_Proc_1_di" bpmnElement="Flow_Proc_1">\n        <di:waypoint x="206" y="513" />\n        <di:waypoint x="250" y="513" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id="Fl